n = int(input())
son = list(map(int, input().split()))

sum = 0
for m in son:
    if m % 2 != 0:
        sum += m
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
print(sum ) 